#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char title[50];
    char author[50];
    int isAvailable;
} Book;

void issueBook(Book *books, int n, int id) {
    for (int i = 0; i < n; i++) {
        if (books[i].id == id) {
            if (books[i].isAvailable) {
                books[i].isAvailable = 0;
                printf("Book '%s' issued successfully!\n", books[i].title);
            } else printf("Book is already issued!\n");
            return;
        }
    }
    printf("Book ID %d not found!\n", id);
}

int main() {
    int n = 2;
    Book *lib = (Book *)malloc(n * sizeof(Book));
    lib[0] = (Book){101, "Data Structures", "Horowitz", 1};
    lib[1] = (Book){102, "Operating Systems", "Silberschatz", 1};
    issueBook(lib, n, 101);
    free(lib);
    return 0;
}

