#include <stdio.h>

typedef struct { int r, c, v; } Term;

int addSparse(Term a[], Term b[], Term sum[]) {
    int i = 1, j = 1, k = 1;
    sum[0].r = a[0].r; sum[0].c = a[0].c;
    while (i <= a[0].v && j <= b[0].v) {
        if (a[i].r == b[j].r && a[i].c == b[j].c) {
            sum[k].r = a[i].r; sum[k].c = a[i].c;
            sum[k++].v = a[i++].v + b[j++].v;
        } else if (a[i].r < b[j].r || (a[i].r == b[j].r && a[i].c < b[j].c)) {
            sum[k++] = a[i++];
        } else {
            sum[k++] = b[j++];
        }
    }
    while (i <= a[0].v) sum[k++] = a[i++];
    while (j <= b[0].v) sum[k++] = b[j++];
    sum[0].v = k - 1;
    return sum[0].v;
}

int main() {
    printf("Sparse matrix addition merges sorted 3-tuple lists.\n");
    return 0;
}

#include <stdio.h>
#define MAX 16

int stack[MAX], top = -1;

void push(int x) {
    if (top == MAX - 1) { printf("Stack OVERFLOW!\n"); return; }
    stack[++top] = x;
    printf("Pushed %d\n", x);
}

int pop() {
    if (top == -1) { printf("Stack UNDERFLOW!\n"); return -1; }
    return stack[top--];
}

void display() {
    if (top == -1) { printf("Stack is EMPTY\n"); return; }
    printf("Stack contents (top to bottom): ");
    for (int i = top; i >= 0; i--) printf("%d ", stack[i]);
    printf("\n");
}

int main() {
    push(10); push(20); push(30);
    display();
    printf("Popped: %d\n", pop());
    display();
    return 0;
}

