#include <stdio.h>
#define MAX 5

typedef struct { int id; char user[20]; int pages; } Job;

Job queue[MAX];
int front = -1, rear = -1, jobCount = 0;

void submitJob(Job j) {
    if (jobCount == MAX) { printf("Printer Queue FULL! Job %d rejected\n", j.id); return; }
    if (front == -1) front = rear = 0;
    else rear = (rear + 1) % MAX;
    queue[rear] = j;
    jobCount++;
    printf("Job %d by '%s' (%d pages) queued. [Total jobs: %d]\n", j.id, j.user, j.pages, jobCount);
}

void printJob() {
    if (jobCount == 0) { printf("No jobs in printer queue!\n"); return; }
    Job j = queue[front];
    if (front == rear) front = rear = -1;
    else front = (front + 1) % MAX;
    jobCount--;
    printf("--> Printed Job %d by '%s'. [Remaining jobs: %d]\n", j.id, j.user, jobCount);
}

int main() {
    submitJob((Job){1, "Admin", 12});
    submitJob((Job){2, "Student1", 5});
    printJob();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int coeff, exp;
    struct Node *next;
} Node;

Node* createHeader() {
    Node *head = (Node*)malloc(sizeof(Node));
    head->exp = -1; head->next = head;
    return head;
}

void insertTerm(Node *head, int c, int e) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->coeff = c; newNode->exp = e;
    Node *curr = head;
    while (curr->next != head) curr = curr->next;
    newNode->next = head;
    curr->next = newNode;
}

int main() {
    Node *p1 = createHeader(), *p2 = createHeader();
    insertTerm(p1, 5, 2); insertTerm(p1, 3, 0);
    insertTerm(p2, 4, 2); insertTerm(p2, 2, 1);
    printf("Circular linked list with header initialized.\n");
    return 0;
}

