Node* addPoly(Node *h1, Node *h2) {
    Node *h3 = createHeader();
    Node *p1 = h1->next, *p2 = h2->next;
    while (p1 != h1 && p2 != h2) {
        if (p1->exp == p2->exp) {
            int sum = p1->coeff + p2->coeff;
            if (sum != 0) insertTerm(h3, sum, p1->exp);
            p1 = p1->next; p2 = p2->next;
        } else if (p1->exp > p2->exp) {
            insertTerm(h3, p1->coeff, p1->exp);
            p1 = p1->next;
        } else {
            insertTerm(h3, p2->coeff, p2->exp);
            p2 = p2->next;
        }
    }
    while (p1 != h1) { insertTerm(h3, p1->coeff, p1->exp); p1 = p1->next; }
    while (p2 != h2) { insertTerm(h3, p2->coeff, p2->exp); p2 = p2->next; }
    return h3;
}
