#include <stdio.h>
#include <string.h>

int isBalanced(char *exp) {
    char stack[100]; int top = -1;
    for (int i = 0; exp[i] != '\0'; i++) {
        char c = exp[i];
        if (c == '(' || c == '{' || c == '[') stack[++top] = c;
        else if (c == ')' || c == '}' || c == ']') {
            if (top == -1) return 0;
            char open = stack[top--];
            if (c == ')' && open != '(') return 0;
            if (c == '}' && open != '{') return 0;
            if (c == ']' && open != '[') return 0;
        }
    }
    return top == -1; // Must be empty
}

int main() {
    printf("Exp '{[()]}' balanced? %s\n", isBalanced("{[()]}") ? "YES" : "NO");
    printf("Exp '{[(])}' balanced? %s\n", isBalanced("{[(])}") ? "YES" : "NO");
    return 0;
}

