#include <stdio.h>
#include <stdlib.h>

typedef struct Part {
    int partId;
    int qty;
    struct Part *next;
} Part;

Part* dispensePart(Part *head, int id, int count) {
    Part *curr = head, *prev = NULL;
    while (curr && curr->partId != id) { prev = curr; curr = curr->next; }
    if (!curr) { printf("Part not found!\n"); return head; }
    curr->qty -= count;
    if (curr->qty <= 0) {
        printf("Stock depleted. Removing Part %d from catalog.\n", id);
        if (!prev) head = curr->next;
        else prev->next = curr->next;
        free(curr);
    } else printf("Dispensed %d items. Remaining: %d\n", count, curr->qty);
    return head;
}

int main() {
    printf("Warehouse machine parts management loaded.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node *left, *right;
} Node;

Node* findMin(Node *n) { while (n->left) n = n->left; return n; }

Node* deleteNode(Node *root, int val) {
    if (!root) return NULL;
    if (val < root->key) root->left = deleteNode(root->left, val);
    else if (val > root->key) root->right = deleteNode(root->right, val);
    else {
        if (!root->left) { Node *r = root->right; free(root); return r; }
        if (!root->right) { Node *l = root->left; free(root); return l; }
        Node *succ = findMin(root->right);
        root->key = succ->key;
        root->right = deleteNode(root->right, succ->key);
    }
    return root;
}

int main() {
    printf("BST deletion with in-order successor loaded.\n");
    return 0;
}

