#include <stdio.h>
#define CITIES 5

int adj[CITIES][CITIES], visited[CITIES];

void dfs(int u) {
    visited[u] = 1;
    for (int v = 0; v < CITIES; v++) {
        if (adj[u][v] == 1 && !visited[v]) dfs(v);
    }
}

int isReachable(int src, int dest) {
    for (int i = 0; i < CITIES; i++) visited[i] = 0;
    dfs(src);
    return visited[dest];
}

int main() {
    adj[0][1] = 1; adj[1][2] = 1; adj[2][3] = 1; // Roads: 0->1->2->3
    printf("Can reach city 3 from city 0? %s\n", isReachable(0, 3) ? "YES" : "NO");
    printf("Can reach city 4 from city 0? %s\n", isReachable(0, 4) ? "YES" : "NO");
    return 0;
}

